#include <bits/stdc++.h>
using namespace std;using ll=long long;
void req(bool c,const string&m){if(!c)throw runtime_error(m);}
unordered_map<string,ll> counts;int maxorder=0;
ll h(const string&w){if(counts.count(w))return counts[w];int n=w.size()+2;req(n<=12,"certified order cap");maxorder=max(maxorder,n);vector<unsigned>r(n,0);r[0]|=2;for(int i=2;i<n;i++){int a=w[i-2]-'0';req(a>=0&&a<4,"letter");for(int j=0;j<i;j++){if(j<2&&(a>>j&1))r[i]|=1u<<j;else r[j]|=1u<<i;}}
 vector<ll>dp((1<<n)*n,0);for(int i=0;i<n;i++)dp[(1<<i)*n+i]=1;for(int mask=1;mask<(1<<n);mask++)for(int v=0;v<n;v++)if(mask>>v&1){ll x=dp[mask*n+v];unsigned next=r[v]&~mask;while(next){int u=__builtin_ctz(next);next&=next-1;dp[((mask|(1<<u))*n)+u]+=x;}}
 ll total=0;for(int v=0;v<n;v++)total+=dp[((1<<n)-1)*n+v];return counts[w]=total;}
map<string,array<set<string>,2>>adj;
map<pair<string,int>,bool> memo;
bool ready(const string&w,int d){if(!d)return true;auto key=make_pair(w,d);if(memo.count(key))return memo[key];for(int b=0;b<2;b++){bool ok=false;for(auto v:adj[w][b])if(ready(v,d-1)){ok=true;break;}if(!ok)return memo[key]=false;}return memo[key]=true;}
int main(int argc,char**argv){req(argc==3,"usage: verify_strategy STRATEGY5.tsv STRATEGY5_SEEDS.txt");ifstream f(argv[1]);string w,v,kind,mapstr;ll a,b;int p,q,rows=0;set<ll> values;while(f>>w>>a>>v>>b>>kind>>mapstr>>p>>q){req(mapstr.size()==4,"map width");string u;for(char c:w){char k=mapstr[c-'0'];req(k>='0'&&k<='4',"map image");if(k!='4')u+=k;}string out;if(kind=="ends"){req(p>=-1&&p<4&&q>=-1&&q<4,"end letters");out=(p<0?string():string(1,'0'+p))+u+(q<0?string():string(1,'0'+q));}else{req(kind=="interior"&&p>=0&&p<=u.size()&&q>=0&&q<4,"interior");out=u.substr(0,p)+char('0'+q)+u.substr(p);}req(out==v,"rewrite mismatch");req(h(w)==a&&h(v)==b,"literal count mismatch");req(b==2*a-1||b==2*a+1,"digit law");adj[w][b==2*a+1].insert(v);values.insert(a);values.insert(b);rows++;}req(f.eof(),"parse ended unexpectedly");ifstream sf(argv[2]);string tag;int seedcount=0;set<ll> seedvalues;while(sf>>tag>>a>>w){req(tag=="seed"&&h(w)==a,"seed");req(ready(w,5),"five-level readiness");seedvalues.insert(a);seedcount++;}req(seedcount==12,"seed number");for(int n=23;n<=45;n+=2)req(seedvalues.count(n),"missing seed");for(int n=23;n<=1471;n+=2)req(values.count(n),"missing finite target");cout<<"{\"status\":\"PASS\",\"rewrite_edges\":"<<rows<<",\"literal_graphs\":"<<counts.size()<<",\"max_order\":"<<maxorder<<",\"seed_count\":"<<seedcount<<",\"strategy_depth\":5,\"odd_target_interval\":[23,1471],\"scope\":\"finite only; no all-order closure\"}\n";}
